tool_input.command:
cd <repo>
cat > /tmp/yamlmap_test.go << 'EOF'
package main

import (
	"fmt"
	"gopkg.in/yaml.v3"
)

func main() {
	m := map[string]any{"zebra": 1, "apple": 2, "mango": 3, "banana": 4}
	for i := 0; i < 5; i++ {
		out, _ := yaml.Marshal(m)
		fmt.Printf("--- run %d ---\n%s", i, out)
	}
}
EOF
cd <repo>
go run /tmp/yamlmap_test.go
rm /tmp/yamlmap_test.go

